package com.example.practice;

import org.jpos.core.Configurable;
import org.jpos.core.Configuration;
import org.jpos.iso.ISOException;
import org.jpos.iso.ISOMsg;
import org.jpos.iso.MUX;
import org.jpos.rc.CMF;
import org.jpos.transaction.Context;
import org.jpos.transaction.TransactionParticipant;
import org.jpos.util.Caller;
import org.jpos.util.NameRegistrar;

import java.io.Serializable;
import java.util.Date;

import static org.jpos.transaction.ContextConstants.REQUEST;
import static org.jpos.transaction.ContextConstants.TIMESTAMP;

/** Asks the card's issuer about a withdrawal and leaves the answer for the participant after it. */
public class AskIssuer implements TransactionParticipant, Configurable {
    public static final String ISSUER_RESPONSE = "ISSUER_RESPONSE";

    private String muxName;
    private long terminalWait;          // how long the ATM waits for its answer, in ms

    @Override
    public void setConfiguration(Configuration cfg) {
        muxName = cfg.get("mux", "issuer");
        terminalWait = cfg.getLong("terminal-wait", 20000);
    }

    @Override
    public int prepare(long id, Serializable context) {
        Context ctx = (Context) context;
        MUX mux = NameRegistrar.getIfExists("mux." + muxName);
        if (mux == null || !mux.isConnected())
            return ctx.getResult().fail(CMF.ISSUER_UNAVAILABLE, Caller.info(), "issuer link down").FAIL();
        try {
            return ask(ctx, mux);
        } catch (ISOException e) {
            return ctx.getResult().fail(CMF.SYSTEM_ERROR, Caller.info(), e.getMessage()).FAIL();
        }
    }

    /** The time, in ms, that this transaction's ATM will still wait for its answer. */
    long remaining(Context ctx) {
        Date received = ctx.get(TIMESTAMP.toString());
        return terminalWait - (System.currentTimeMillis() - received.getTime());
    }

    /**
     * Asks the issuer about the request under REQUEST and leaves its answer, if one comes, under
     * ISSUER_RESPONSE. Returns this participant's vote.
     */
    int ask(Context ctx, MUX mux) throws ISOException {
        long left = remaining(ctx);
        if (left <= 0)
            return ctx.getResult().fail(CMF.SYSTEM_ERROR, Caller.info(),
                "ATM gave up %d ms ago", -left).FAIL();
        ISOMsg request = ctx.get(REQUEST.toString());
        ISOMsg response = mux.request((ISOMsg) request.clone(), left);
        if (response != null)
            ctx.put(ISSUER_RESPONSE, response);
        return PREPARED | NO_JOIN | READONLY;
    }
}

import com.example.practice.AskIssuer;
import org.jpos.core.SimpleConfiguration;
import org.jpos.iso.ISOMsg;
import org.jpos.iso.ISOResponseListener;
import org.jpos.iso.MUX;
import org.jpos.rc.Result;
import org.jpos.transaction.Context;
import org.jpos.transaction.ContextConstants;
import org.jpos.transaction.TransactionConstants;
import org.jpos.util.NameRegistrar;

import java.util.Date;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        Logger root = Logger.getLogger("");
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            NameRegistrar.register("mux.tryit-issuer", new MUX() {
                @Override
                public ISOMsg request(ISOMsg m, long timeout) {
                    System.out.println("  issuer asked about STAN " + m.getString(11) + " with " + timeout / 1000 + " s to answer");
                    ISOMsg r = (ISOMsg) m.clone();
                    r.set(0, "0210");
                    r.set(39, "00");
                    return r;
                }
                @Override public void request(ISOMsg m, long t, ISOResponseListener l, Object h) { }
                @Override public void send(ISOMsg m) { }
                @Override public boolean isConnected() { return true; }
            });
            SimpleConfiguration cfg = new SimpleConfiguration();
            cfg.put("mux", "tryit-issuer");
            cfg.put("terminal-wait", "20000");
            AskIssuer ask = new AskIssuer();
            ask.setConfiguration(cfg);
            System.out.println("arrived just now: " + run(ask, "007301", 0));
            System.out.println("arrived 12 s ago: " + run(ask, "007302", 12_000));
            System.out.println("arrived 25 s ago: " + run(ask, "007303", 25_000));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        } finally {
            NameRegistrar.unregister("mux.tryit-issuer");
        }
    }

    private static String run(AskIssuer ask, String stan, long ageMs) throws Exception {
        ISOMsg m = new ISOMsg("0200");
        m.set(2, "4012888888881881");
        m.set(3, "010000");
        m.set(4, "000000006000");
        m.set(11, stan);
        m.set(41, "ATM00562");
        Context ctx = new Context();
        ctx.put(ContextConstants.REQUEST.toString(), m);
        ctx.put(ContextConstants.TIMESTAMP.toString(), new Date(System.currentTimeMillis() - ageMs));
        int vote = ask.prepare(1L, ctx);
        if ((vote & TransactionConstants.PREPARED) != 0) {
            ISOMsg answer = ctx.get(AskIssuer.ISSUER_RESPONSE);
            return "goes on, issuer answered " + (answer == null ? null : answer.getString(39));
        }
        Result.Entry failure = ctx.getResult().failure();
        return "stops, cause " + (failure == null ? "none recorded" : failure.getIrc());
    }
}

